39	    /**
40	     * Derives an owner's preferred contact channel for the read-only {@code contactPreference}
41	     * field: {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
42	     */
43	    @Named("formatContactPreference")
44	    default String formatContactPreference(Owner owner) {
45	        if (owner == null) {
46	            return null;
47	        }
48	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
49	        return hasEmail ? "EMAIL" : "PHONE";
50	    }
51	
52	    /**
53	     * Derives an owner's {@code locality} from its region-and-hash customer code: the region is the
54	     * segment of the {@code '<REGION>-<HASH8>'} code before the first {@code '-'}, so the locality
55	     * always agrees with the identity's region (which itself prefers the postcode over the city,
56	     * defaulting to {@code 'UNKNOWN'}). Returns {@code 'UNKNOWN'} when no customer code is present.
57	     */
58	    @Named("formatLocality")
59	    default String formatLocality(Owner owner) {
60	        if (owner == null) {
61	            return null;
62	        }
63	        String code = owner.getCustomerCode();
64	        if (code == null || code.isBlank()) {
65	            return "UNKNOWN";
66	        }
67	        int dash = code.indexOf('-');
68	        return dash < 0 ? code : code.substring(0, dash);
69	    }
