71	    /**
72	     * Fixed region-to-timezone table mapping each canonical region to its IANA timezone name.
73	     */
74	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
75	        "NSW", "Australia/Sydney",
76	        "VIC", "Australia/Melbourne",
77	        "QLD", "Australia/Brisbane");
78	
79	    /**
80	     * Derives an owner's {@code timezone} as the IANA timezone name for its locality/region, using
81	     * the fixed region-to-timezone table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
82	     * QLD-&gt;Australia/Brisbane). The region is taken from {@link #formatLocality(Owner)}, so the
83	     * timezone always agrees with the reported locality. Returns {@code null} when the region is not
84	     * in the table (e.g. {@code 'UNKNOWN'}).
85	     */
86	    @Named("formatTimezone")
87	    default String formatTimezone(Owner owner) {
88	        if (owner == null) {
89	            return null;
90	        }
91	        return REGION_TIMEZONE.get(formatLocality(owner));
