93	
94	    /**
95	     * Computes an owner's membership points for the read-only {@code membershipPoints} field. Points
96	     * start at 0 and accumulate: 2 when an email address is present, 1 when the owner had no
97	     * namesakes at creation (namesakeCount is 0), 2 for a household of 3 or more members, and 3 for
98	     * tenure of more than 365 days (measured from the registration date to the current date).
99	     */
100	    @Named("formatMembershipPoints")
101	    default Integer formatMembershipPoints(Owner owner) {
102	        if (owner == null) {
103	            return null;
104	        }
105	        int points = 0;
106	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
107	        if (hasEmail) {
108	            points += 2;
109	        }
110	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
111	        if (noNamesakes) {
112	            points += 1;
113	        }
114	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
115	            points += 2;
116	        }
117	        if (owner.getRegistrationDate() != null
118	            && ChronoUnit.DAYS.between(owner.getRegistrationDate(), LocalDate.now()) > 365) {
119	            points += 3;
120	        }
121	        return points;
122	    }
123	
124	    /**
125	     * Derives an owner's numeric membership level for the read-only {@code membershipLevel} field
126	     * from its membership points: 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for
127	     * 6 or more points.
128	     */
129	    @Named("formatMembershipLevel")
130	    default Integer formatMembershipLevel(Owner owner) {
131	        Integer points = formatMembershipPoints(owner);
132	        if (points == null) {
133	            return null;
134	        }
135	        if (points <= 1) {
136	            return 1;
137	        }
138	        if (points <= 3) {
139	            return 2;
140	        }
141	        if (points <= 5) {
142	            return 3;
143	        }
144	        return 4;
