153	    default String formatMembershipNumber(Owner owner) {
154	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
155	            return null;
156	        }
157	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
158	    }
159	
160	    /**
161	     * Computes the Luhn check digit (0-9) over the digits contained in the owner's
162	     * {@code customerCode} for the read-only {@code checkDigit} field. Null when the
163	     * customer code is absent.
164	     */
165	    @Named("formatCheckDigit")
166	    default Integer formatCheckDigit(Owner owner) {
167	        if (owner == null || owner.getCustomerCode() == null) {
168	            return null;
169	        }
170	        String code = owner.getCustomerCode();
171	        int sum = 0;
172	        boolean dbl = true;
173	        for (int i = code.length() - 1; i >= 0; i--) {
174	            char c = code.charAt(i);
175	            if (c < '0' || c > '9') {
176	                continue;
177	            }
178	            int d = c - '0';
179	            if (dbl) {
180	                d *= 2;
181	                if (d > 9) {
182	                    d -= 9;
183	                }
184	            }
185	            sum += d;
186	            dbl = !dbl;
187	        }
188	        return (10 - (sum % 10)) % 10;
189	    }
190	
191	    /**
192	     * Formats an owner's stored names as {@code 'LastName, FirstName'} for the read-only
193	     * {@code displayName} field.
194	     */
195	    @Named("formatDisplayName")
196	    default String formatDisplayName(Owner owner) {
197	        return owner == null ? null : owner.getLastName() + ", " + owner.getFirstName();
198	    }
