234	     * {@code '  12  main  st '} becomes {@code '12 MAIN STREET'}). The required-field rule is
235	     * enforced separately; an address blank after normalization is rejected.
236	     */
237	    @Named("normalizeAddress")
238	    default String normalizeAddress(String address) {
239	        return AddressNormalizer.normalize(address);
240	    }
241	
