243	     * Normalizes a telephone number for persistence into canonical E.164 form (e.g.
244	     * {@code '0412 345 678'} becomes {@code '+61412345678'}). The formability rule is
245	     * enforced separately by {@code TelephoneValidation}.
246	     */
247	    @Named("normalizeTelephone")
248	    default String normalizeTelephone(String telephone) {
249	        return TelephoneNormalizer.toE164(telephone);
