257	        OwnerPageDto ownerPageDto = new OwnerPageDto();
258	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
259	        ownerPageDto.setPage(ownerPage.getNumber());
260	        ownerPageDto.setSize(ownerPage.getSize());
261	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
262	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
263	        return ownerPageDto;
264	    }
